<script setup>import{onMounted,ref}from'vue';import{request}from'../api';const org='DEMO-PRIV',data=ref({activities:[],requests:[],activeConsents:0,overdueRequests:0}),busy=ref(false),error=ref('');async function load(){try{data.value=await request('/api/privacy-ops/dashboard?organizationCode='+org)}catch(e){error.value=e.message}}async function scenario(){busy.value=true;error.value='';try{const x=Date.now(),activity=await request('/api/privacy-ops/activities',{method:'POST',body:JSON.stringify({organizationCode:org,activityNo:'ROPA-'+x,name:'客户个性化推荐',department:'市场部',owner:'隐私负责人',lawfulBasis:'单独同意',dataCategories:'联系方式、行为偏好',purpose:'提供个性化服务',sensitiveData:true,crossBorder:false,retentionDays:365})}),pia=await request(`/api/privacy-ops/activities/${activity.id}/assessments`,{method:'POST',body:JSON.stringify({riskDescription:'敏感个人信息画像风险',mitigations:'最小化、加密、权限隔离和访问审计',residualRisk:'MEDIUM',reviewer:'隐私官'})});await request(`/api/admin/privacy-ops/assessments/${pia.id}/approve`,{method:'POST'});await request(`/api/privacy-ops/activities/${activity.id}/submit`,{method:'POST'});await request(`/api/admin/privacy-ops/activities/${activity.id}/approve`,{method:'POST'});await request('/api/privacy-ops/consents',{method:'POST',body:JSON.stringify({organizationCode:org,subjectRef:'USER-'+x,purposeCode:'RECOMMEND',noticeVersion:'v2',source:'WEB',proofReference:'PROOF-'+x})});await load()}catch(e){error.value=e.message}finally{busy.value=false}}onMounted(load)</script>
<template><section class="dw-head"><div><span>PRIVACY OPERATIONS</span><h3>个人信息处理活动与权利请求</h3><p>以处理活动、PIA、合法性基础、同意和主体请求证明合规。</p></div><button @click="scenario" :disabled="busy">{{busy?'合规流转中…':'创建PIA审批场景'}}</button></section><p v-if="error" class="err">{{error}}（批准需要管理员账号）</p><section class="metrics"><article><span>处理活动</span><b>{{data.activities.length}}</b></article><article><span>已批准</span><b>{{data.activities.filter(a=>a.status==='APPROVED').length}}</b></article><article><span>有效同意</span><b>{{data.activeConsents}}</b></article><article><span>逾期请求</span><b>{{data.overdueRequests}}</b></article></section><section class="grid"><article><h4>处理活动台账</h4><table><tr><th>编号/名称</th><th>责任部门</th><th>风险特征</th><th>保留</th><th>状态</th></tr><tr v-for="a in data.activities" :key="a.id"><td><b>{{a.activityNo}}</b><small>{{a.name}}</small></td><td>{{a.department}} / {{a.owner}}</td><td>{{a.sensitiveData?'敏感':''}} {{a.crossBorder?'跨境':''}}</td><td>{{a.retentionDays}}天</td><td><i>{{a.status}}</i></td></tr></table></article><article><h4>主体请求</h4><div class="request" v-for="r in data.requests" :key="r.id"><b>{{r.requestNo}} · {{r.requestType}}</b><span>{{r.subjectRef}}</span><i>{{r.status}}</i></div></article></section></template>
<style scoped>.dw-head{display:flex;justify-content:space-between;align-items:end;background:#343451;color:#fff;padding:26px 30px;border-radius:14px}.dw-head span{font-size:11px;letter-spacing:.16em;color:#b8b8dc}.dw-head h3{font-size:25px;margin:7px 0}.dw-head p{margin:0;color:#d5d5e4}.dw-head button{background:#8fd0b5;border:0;border-radius:8px;padding:12px 18px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metrics article,.grid article{background:#fff;border:1px solid #e2e2e8;border-radius:12px;padding:20px}.metrics b{display:block;font-size:29px;margin-top:8px}.metrics span{color:#707080}.grid{display:grid;grid-template-columns:1.6fr 1fr;gap:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px;border-bottom:1px solid #eeeef2}td small{display:block;color:#777787}.request{display:grid;gap:5px;border-bottom:1px solid #eeeef2;padding:11px 0}.request i,td i{font-style:normal;color:#276e58}.err{color:#a43b35}@media(max-width:900px){.metrics,.grid{grid-template-columns:1fr 1fr}}</style>
